async function checkAllDownloadSources(limit = 20) {
  const sources = await prisma.downloadSource.findMany({
    where: { isActive: true },
    orderBy: { lastCheckedAt: "asc" },
    // 优先扫描从未检测或最早检测的
    take: limit
  });
  const results = [];
  const chunkSize = 5;
  for (let i = 0; i < sources.length; i += chunkSize) {
    const chunk = sources.slice(i, i + chunkSize);
    const chunkResults = await Promise.all(
      chunk.map((s) => checkSingleDownloadSource(s.id).catch((e) => ({
        sourceId: s.id,
        url: s.url,
        httpStatus: 0,
        healthStatus: import_client27.LinkHealthStatus.BROKEN,
        responseTimeMs: 0,
        errorMessage: e.message,
        isSafeUrl: true
      })))
    );
    results.push(...chunkResults);
  }
  const healthyCount = results.filter((r) => r.healthStatus === import_client27.LinkHealthStatus.HEALTHY).length;
  const brokenCount = results.filter((r) => r.healthStatus === import_client27.LinkHealthStatus.BROKEN).length;
  const redirectedCount = results.filter((r) => r.healthStatus === import_client27.LinkHealthStatus.REDIRECTED).length;
  const needsReviewCount = results.filter((r) => r.healthStatus === import_client27.LinkHealthStatus.NEEDS_REVIEW).length;
  return {
    scannedCount: results.length,
    healthyCount,
    brokenCount,
    redirectedCount,
    needsReviewCount,
    results
  };
}
async function listLinkCheckLogs(params) {
  const page = Math.max(1, params.page || 1);
  const limit = Math.min(100, Math.max(1, params.limit || 20));
  const skip = (page - 1) * limit;
  const where = {};
  if (params.healthStatus) where.healthStatus = params.healthStatus;
  if (params.sourceId) where.sourceId = params.sourceId;
  const [total, items] = await Promise.all([
    prisma.linkCheckLog.count({ where }),
    prisma.linkCheckLog.findMany({
      where,
      skip,
      take: limit,
      orderBy: { checkedAt: "desc" },
      include: {
        downloadSource: {
          select: {
            id: true,
            sourceName: true,
            url: true,
            version: {
              select: {
                version: true,
                software: { select: { id: true, name: true, slug: true } }
              }
            }
          }
        }
      }
    })
  ]);
  return {
    items,
    pagination: {
      page,
      limit,
      total,
      totalPages: Math.ceil(total / limit)
    }
  };
}

