async function jobRoutes(server) {
  await initDefaultJobs();
  server.get(
    "/api/v1/admin/jobs",
    { preHandler: [requireAuth, requireRole([import_client30.Role.ADMIN, import_client30.Role.SUPER_ADMIN])] },
    async (req, reply) => {
      const jobs = await prisma.job.findMany({
        orderBy: { createdAt: "asc" },
        include: {
          runs: {
            orderBy: { startedAt: "desc" },
            take: 1
          },
          _count: { select: { runs: true } }
        }
      });
      return reply.send({
        success: true,
        data: jobs.map((j) => ({
          ...j,
          lastRun: j.runs[0] || null
        }))
      });
    }
  );
  server.post(
    "/api/v1/admin/jobs/:id/trigger",
    { preHandler: [requireAuth, requireRole([import_client30.Role.ADMIN, import_client30.Role.SUPER_ADMIN])] },
    async (req, reply) => {
      const { id } = req.params;
      const result = await runJob(id);
      return reply.status(result.success ? 200 : 409).send({
        success: result.success,
        data: result,
        message: result.message
      });
    }
  );
  server.get(
    "/api/v1/admin/jobs/:id/runs",
    { preHandler: [requireAuth, requireRole([import_client30.Role.ADMIN, import_client30.Role.SUPER_ADMIN])] },
    async (req, reply) => {
      const { id } = req.params;
      const { page = "1", limit = "10" } = req.query;
      const pageNum = Math.max(1, parseInt(page, 10) || 1);
      const limitNum = Math.min(50, Math.max(1, parseInt(limit, 10) || 10));
      const skip = (pageNum - 1) * limitNum;
      const [total, runs] = await Promise.all([
        prisma.jobRun.count({ where: { jobId: id } }),
        prisma.jobRun.findMany({
          where: { jobId: id },
          skip,
          take: limitNum,
          orderBy: { startedAt: "desc" }
        })
      ]);
      return reply.send({
        success: true,
        data: runs,
        pagination: {
          page: pageNum,
          limit: limitNum,
          total,
          totalPages: Math.ceil(total / limitNum)
        }
      });
    }
  );
  const updateJobSchema = external_exports.object({
    enabled: external_exports.boolean().optional(),
    intervalSec: external_exports.number().int().min(60).optional(),
    description: external_exports.string().optional()
  });
  server.patch(
    "/api/v1/admin/jobs/:id",
    { preHandler: [requireAuth, requireRole([import_client30.Role.SUPER_ADMIN])] },
    async (req, reply) => {
      const { id } = req.params;
      const parseRes = updateJobSchema.safeParse(req.body);
      if (!parseRes.success) {
        return reply.status(400).send({
          success: false,
          error: { code: "VALIDATION_ERROR", message: "\u53C2\u6570\u6821\u9A8C\u5931\u8D25" }
        });
      }
      const updated = await prisma.job.update({
        where: { id },
        data: parseRes.data
      });
      return reply.send({
        success: true,
        data: updated
      });
    }
  );
}

