    const metaDescription = `${item.summary} \u8F6F\u6E38\u90E8\u843D\u6E38\u620F\u9891\u9053\u4E3A\u60A8\u63D0\u4F9B ${item.name} \u7684\u5B98\u65B9\u53D1\u884C\u4FE1\u606F\u3001\u652F\u6301\u5E73\u53F0\uFF08${platforms}\uFF09\u3001\u6B63\u89C4\u5206\u53D1\u6E20\u9053\u53CA\u5B89\u88C5\u6307\u5F15\u3002`;
